  1→import { computed } from "@angular/core";
  2→import {
  3→  patchState,
  4→  signalStore,
  5→  withComputed,
  6→  withMethods,
  7→  withState,
  8→} from "@ngrx/signals";
  9→import type {
 10→  EventSnapshot,
 11→  IssueSnapshot,
 12→  SnapshotWithScore,
 13→  TimeSnapshot,
 14→} from "./engine-api.service";
 15→import type { ActiveDecision, ScenarioContext } from "./decision-api.service";
 16→import type { ScoreChange, SystemSnapshot, SystemStateChange } from "./generated/state-changes.types";
 17→import { formatTimeMs } from "./format-time";
 18→
 19→export interface ParticipantPresence {
 20→  id: string;
 21→  display_name: string;
 22→  role: string | null;
 23→  connected: boolean;
 24→}
 25→
 26→interface ScoreState {
 27→  totalScore: number;
 28→  turnNumber: number;
 29→  nextDecisionTimeMs: number;
 30→  stress: number;
 31→}
 32→
 33→interface ExerciseState {
 34→  exerciseId: number | null;
 35→  title: string;
 36→  phase: string;
 37→  gameMode: string;
 38→  practiceMode: boolean;
 39→  playTimeMs: number;
 40→  realTimeMs: number;
 41→  speedFactor: number;
 42→  paused: boolean;
 43→  events: EventSnapshot[]; // domain: "injects"
 44→  issues: IssueSnapshot[]; // domain: "defects"
 45→  decisions: ActiveDecision[];
 46→  systems: SystemSnapshot[];
 47→  participants: ParticipantPresence[];
 48→  context: ScenarioContext | null;
 49→  participantId: string;
 50→  playerRole: string;
 51→  playerType: string;
 52→  score: ScoreState | null;
 53→  loading: boolean;
 54→  error: string | null;
 55→}
 56→
 57→const initialState: ExerciseState = {
 58→  exerciseId: null,
 59→  title: "",
 60→  phase: "setup",
 61→  gameMode: "classic",
 62→  practiceMode: false,
 63→  playTimeMs: 0,
 64→  realTimeMs: 0,
 65→  speedFactor: 1,
 66→  paused: true,
 67→  events: [],
 68→  issues: [],
 69→  decisions: [],
 70→  systems: [],
 71→  participants: [],
 72→  context: null,
 73→  participantId: "",
 74→  playerRole: "player",
 75→  playerType: "advisor",
 76→  score: null,
 77→  loading: false,
 78→  error: null,
 79→};
 80→
 81→export const ExerciseStore = signalStore(
 82→  withState(initialState),
 83→
 84→  withComputed((store) => ({
 85→    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
 86→    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
 87→    activeEvents: computed(() =>
 88→      store.events().filter((e) => e.lifecycle === "running"),
 89→    ), // active injects
 90→    scheduledEvents: computed(() =>
 91→      store.events().filter((e) => e.lifecycle === "scheduled"),
 92→    ), // scheduled injects
 93→    completedEvents: computed(() =>
 94→      store.events().filter((e) => e.lifecycle === "completed"),
 95→    ), // completed injects
 96→    activeIssues: computed(() =>
 97→      store.issues().filter((i) => i.lifecycle === "active"),
 98→    ), // active defects
 99→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
100→    decisionCountdownMs: computed(() => {
101→      const decision = store
102→        .decisions()
103→        .find((d) => d.status === "open" && d.timeout_ms > 0);
104→      if (!decision) return null;
105→      const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
106→      return Math.max(0, deadline - store.playTimeMs());
107→    }),
108→    /** Countdown clock: decision timer when a decision is open, otherwise time to next event. */
109→    turnCountdownClock: computed(() => {
110→      // Prefer decision countdown when an open decision has a timeout
111→      const decision = store
112→        .decisions()
113→        .find((d) => d.status === "open" && d.timeout_ms > 0);
114→      if (decision) {
115→        const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
116→        return formatTimeMs(Math.max(0, deadline - store.playTimeMs()));
117→      }
118→      const pt = store.playTimeMs();
119→      const nextEvent = store
120→        .events()
121→        .filter((e) => e.lifecycle === "scheduled" && e.scheduled_pt_ms > pt)
122→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
123→      if (!nextEvent) return null;
124→      const remaining = Math.max(0, nextEvent.scheduled_pt_ms - pt);
125→      return formatTimeMs(remaining);
126→    }),
127→    issuesWithCountdown: computed(() => {
128→      const pt = store.playTimeMs();
129→      return store
130→        .issues()
131→        .filter(
132→          (i) =>
133→            i.lifecycle === "active" &&
134→            i.auto_resolve_ms > 0 &&
135→            i.activated_at_pt_ms !== null,
136→        )
137→        .map((i) => {
138→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
139→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
140→          return { ...i, remaining_ms: remaining };
141→        });
142→    }),
143→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
144→    openDecisions: computed(() =>
145→      store.decisions().filter((d) => d.status === "open"),
146→    ),
147→    hasOpenDecision: computed(
148→      () => store.decisions().filter((d) => d.status === "open").length > 0,
149→    ),
150→    connectedParticipants: computed(() =>
151→      store.participants().filter((p) => p.connected),
152→    ),
153→    connectedCount: computed(
154→      () => store.participants().filter((p) => p.connected).length,
155→    ),
156→    isCollaborative: computed(
157→      () => store.gameMode() === "simple_collaborative",
158→    ),
159→    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
160→    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
161→    isPracticeMode: computed(() => store.practiceMode()),
162→    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
163→      switch (store.phase()) {
164→        case "running":
165→          return "default";
166→        case "paused":
167→          return "secondary";
168→        case "completed":
169→          return "destructive";
170→        default:
171→          return "secondary";
172→      }
173→    }),
174→  })),
175→
176→  withMethods((store) => ({
177→    setExerciseId(id: number): void {
178→      patchState(store, { exerciseId: id });
179→    },
180→
181→    applySnapshot(snapshot: SnapshotWithScore): void {
182→      patchState(store, {
183→        exerciseId: snapshot.exercise_id,
184→        title: snapshot.title,
185→        phase: snapshot.phase,
186→        playTimeMs: snapshot.time.play_time_ms,
187→        realTimeMs: snapshot.time.real_time_ms,
188→        speedFactor: snapshot.time.factor,
189→        paused: snapshot.time.paused,
190→        events: snapshot.events,
191→        issues: snapshot.issues,
192→        systems: snapshot.systems ?? store.systems(),
193→        decisions: snapshot.decisions ?? store.decisions(),
194→        score: snapshot.score
195→          ? {
196→              totalScore: snapshot.score.total_score,
197→              stress: snapshot.score.stress,
198→              turnNumber: snapshot.score.turn_number,
199→              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
200→            }
201→          : store.score(),
202→        loading: false,
203→        error: null,
204→      });
205→    },
206→
207→    applyTimeUpdate(time: TimeSnapshot): void {
208→      patchState(store, {
209→        playTimeMs: time.play_time_ms,
210→        realTimeMs: time.real_time_ms,
211→        speedFactor: time.factor,
212→        paused: time.paused,
213→      });
214→    },
215→
216→    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
217→    tick(wallDeltaMs: number): void {
218→      if (store.paused()) return;
219→      const factor = store.speedFactor();
220→      patchState(store, {
221→        realTimeMs: store.realTimeMs() + wallDeltaMs,
222→        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
223→      });
224→    },
225→
226→    applyPhaseChange(phase: string): void {
227→      patchState(store, { phase });
228→    },
229→
230→    updateEvent(eventId: string, lifecycle: string): void {
231→      const events = store
232→        .events()
233→        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
234→      patchState(store, { events });
235→    },
236→
237→    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
238→      const issues = store
239→        .issues()
240→        .map((i) =>
241→          i.id === issueId
242→            ? { ...i, lifecycle, released: released ?? i.released }
243→            : i,
244→        );
245→      patchState(store, { issues });
246→    },
247→
248→    setLoading(loading: boolean): void {
249→      patchState(store, { loading });
250→    },
251→
252→    setError(error: string): void {
253→      patchState(store, { error, loading: false });
254→    },
255→
256→    applyDecisions(decisions: ActiveDecision[]): void {
257→      patchState(store, { decisions });
258→    },
259→
260→    setContext(ctx: ScenarioContext): void {
261→      patchState(store, { context: ctx });
262→    },
263→
264→    setParticipantId(id: string): void {
265→      patchState(store, { participantId: id });
266→    },
267→
268→    setPlayerRole(role: string): void {
269→      patchState(store, { playerRole: role });
270→    },
271→
272→    closeDecision(decisionId: string, selectedOptionIds?: string[]): void {
273→      const decisions = store
274→        .decisions()
275→        .map((d) =>
276→          d.id === decisionId
277→            ? { ...d, status: "closed", selected_option_ids: selectedOptionIds ?? d.selected_option_ids }
278→            : d,
279→        );
280→      patchState(store, { decisions });
281→    },
282→
283→    updatePresence(participants: ParticipantPresence[]): void {
284→      patchState(store, { participants });
285→    },
286→
287→    setGameMode(mode: string): void {
288→      patchState(store, { gameMode: mode });
289→    },
290→
291→    setPracticeMode(practice: boolean): void {
292→      patchState(store, { practiceMode: practice });
293→    },
294→
295→    setPlayerType(playerType: string): void {
296→      patchState(store, { playerType });
297→    },
298→
299→    setSpeedFactor(factor: number): void {
300→      patchState(store, { speedFactor: factor });
301→    },
302→
303→    applyScoreChange(change: Pick<ScoreChange, "total_score" | "stress" | "next_decision_time_ms" | "turn_number">): void {
304→      patchState(store, {
305→        score: {
306→          totalScore: change.total_score,
307→          stress: change.stress,
308→          nextDecisionTimeMs: change.next_decision_time_ms,
309→          turnNumber: change.turn_number,
310→        },
311→      });
312→    },
313→
314→    applyRecommendation(
315→      decisionId: string,
316→      participantId: string,
317→      optionId: string,
318→    ): void {
319→      const decisions = store.decisions().map((d) =>
320→        d.id === decisionId
321→          ? {
322→              ...d,
323→              recommendations: {
324→                ...d.recommendations,
325→                [participantId]: optionId,
326→              },
327→            }
328→          : d,
329→      );
330→      patchState(store, { decisions });
331→    },
332→
333→    applySystemChange(change: Pick<SystemStateChange, "system_id" | "action" | "power" | "operational">): void {
334→      const systems = store.systems().map((s) =>
335→        s.system_id === change.system_id
336→          ? { ...s, power: change.power, operational: change.operational }
337→          : s,
338→      );
339→      patchState(store, { systems });
340→    },
341→  })),
342→);
