  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  input,
  5→  inject,
  6→  ElementRef,
  7→  OnChanges,
  8→  AfterViewInit,
  9→} from "@angular/core";
 10→import { AnimationService } from "../core/animation.service";
 11→import { StressBarComponent } from "./stress-bar.component";
 12→
 13→export interface ScoreState {
 14→  totalScore: number;
 15→  turnNumber: number;
 16→  nextDecisionTimeMs: number;
 17→  stress: number;
 18→}
 19→
 20→@Component({
 21→  selector: "tfc-score-bar",
 22→  changeDetection: ChangeDetectionStrategy.OnPush,
 23→  imports: [StressBarComponent],
 24→  template: `
 25→    <div class="score-bar">
 26→      <div
 27→        class="score-bar__vignette"
 28→        [class.score-bar__vignette--active]="stressFlash"
 29→      ></div>
 30→      <span class="text-xs text-primary uppercase tracking-wide font-semibold"
 31→        >Turn {{ score()?.turnNumber }}</span
 32→      >
 33→      <span class="text-xs text-muted-foreground uppercase tracking-wide"
 34→        >Score</span
 35→      >
 36→      <span class="score-bar__value">{{ displayScore }}</span>
 37→      <tfc-stress-bar [stress]="score()?.stress ?? 0" />
 38→      <span class="flex-1"></span>
 39→      @if (countdownMs() !== null && countdownMs()! > 0) {
 40→        <span class="score-bar__countdown" [class.score-bar__countdown--urgent]="countdownMs()! < 30000">
 41→          {{ formattedCountdown }}
 42→        </span>
 43→      } @else if (score()?.nextDecisionTimeMs; as ms) {
 44→        <span class="text-xs text-muted-foreground">
 45→          Next in {{ ms / 1000 }}s
 46→        </span>
 47→      }
 48→    </div>
 49→  `,
 50→})
 51→export class ScoreBarComponent implements AfterViewInit, OnChanges {
 52→  readonly score = input<ScoreState | null>(null);
 53→  readonly countdownMs = input<number | null>(null);
 54→  private readonly anim = inject(AnimationService);
 55→  private readonly el = inject(ElementRef);
 56→  private initialized = false;
 57→  private prevScore = 0;
 58→  private prevStress = 0;
 59→  protected displayScore = 0;
 60→  protected stressFlash = false;
 61→
 62→  protected get formattedCountdown(): string {
 63→    const ms = this.countdownMs() ?? 0;
 64→    const totalSeconds = Math.max(0, Math.ceil(ms / 1000));
 65→    const minutes = Math.floor(totalSeconds / 60);
 66→    const seconds = totalSeconds % 60;
 67→    return `${minutes}:${String(seconds).padStart(2, "0")}`;
 68→  }
 69→
 70→  ngAfterViewInit(): void {
 71→    this.initialized = true;
 72→    this.displayScore = this.score()?.totalScore ?? 0;
 73→    this.prevScore = this.displayScore;
 74→    this.prevStress = this.score()?.stress ?? 0;
 75→  }
 76→
 77→  ngOnChanges(): void {
 78→    if (!this.initialized) return;
 79→    const s = this.score();
 80→    if (!s) return;
 81→
 82→    if (s.totalScore !== this.prevScore) {
 83→      this.anim.counter(this.prevScore, s.totalScore, (v) => {
 84→        this.displayScore = v;
 85→      });
 86→      this.prevScore = s.totalScore;
 87→    }
 88→
 89→    if (s.stress > this.prevStress) {
 90→      this.stressFlash = true;
 91→      this.anim.shake(
 92→        this.el.nativeElement.querySelector(".score-bar"),
 93→        2,
 94→        0.3,
 95→      );
 96→      setTimeout(() => {
 97→        this.stressFlash = false;
 98→      }, 800);
 99→    }
100→    this.prevStress = s.stress;
101→  }
102→}
