191→  protected readonly playing = signal(false);
192→  protected readonly playbackSpeed = signal(1);
193→  private playTimer: ReturnType<typeof setInterval> | null = null;
194→
195→  protected readonly sortedLog = computed(() =>
196→    [...this.auditLog()].sort((a, b) => a.play_time_ms - b.play_time_ms),
197→  );
198→
199→  protected readonly visibleEntries = computed(() =>
200→    this.sortedLog().slice(0, this.replayIndex()),
201→  );
202→
203→  protected readonly currentEntry = computed(() => {
204→    const idx = this.replayIndex();
205→    const log = this.sortedLog();
206→    return idx > 0 ? log[idx - 1] : null;
