 69→  private sub: Subscription | null = null;
 70→  private connSub: Subscription | null = null;
 71→
 72→  protected readonly activeDecisions = computed(() => {
 73→    const role = this.store.playerRole();
 74→    return this.store.openDecisions().filter((d) => {
 75→      if (!d.target_roles || d.target_roles.length === 0) return true;
 76→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 77→      return d.target_roles.includes(role);
 78→    });
 79→  });
 80→
 81→  protected readonly isMultiRole = computed(() => {
 82→    const role = this.store.playerRole();
 83→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 84→  });
 85→
 86→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 87→
 88→  protected readonly currentTurnEvent = computed(() => {
 89→    const decisions = this.activeDecisions();
 90→    if (decisions.length === 0) return null;
 91→    const decision = decisions[0];
 92→    if (!decision.event_id) return null;
 93→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 94→  });
 95→
 96→  protected readonly roleCards = computed(() => {
 97→    const allRoles = this.store.context()?.roles ?? [];
 98→    const event = this.currentTurnEvent();
 99→    const decision = this.activeDecisions()[0] ?? null;
100→    const role = this.store.playerRole();
101→    const multiRole = this.isMultiRole();
102→    const playerRoleDef = allRoles.find((r) => r.id === role);
103→    const showDecisionMaker =
104→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode()
105→      || playerRoleDef?.player_type === "decision_maker";
106→    // Single-role players see only their own role card
107→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
108→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker, allRoles);
109→  });
110→
111→  private _lastDecisionId: string | null = null;
112→  private readonly resetSubmittedRolesEffect = effect(() => {
113→    const id = this.activeDecisions()[0]?.id ?? null;
114→    // Only reset when the decision ID actually changes (not on every WS push)
115→    if (id && id !== this._lastDecisionId) {
116→      this._lastDecisionId = id;
117→      this.submittedRoles.set(new Set());
118→    }
119→  });
120→
121→  // Turn advancement is backend-driven: closing a decision triggers the
122→  // next event in sequence automatically via engine.force_trigger_next_decision.
123→
124→  ngOnInit(): void {
125→    const params = this.route.snapshot.queryParams;
126→    const id = Number(params["exerciseId"] ?? 1);
127→    const pId = String(params["participantId"] ?? "");
128→    const role = String(params["role"] ?? "player");
129→    const gameMode = String(params["gameMode"] ?? "");
130→    this.exerciseId.set(id);
131→    this.participantId.set(pId);
132→    this.store.setParticipantId(pId);
133→    this.store.setPlayerRole(role);
134→    if (gameMode) {
135→      this.store.setGameMode(gameMode);
136→    }
137→    const practiceMode = params["practiceMode"] === "true";
138→    this.store.setPracticeMode(practiceMode);
139→    this.ws.connect(id, "player", pId || undefined);
140→    this.sub = this.ws.messages$.subscribe((msg) =>
141→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped()),
142→    );
143→    this.loadSnapshot(id);
144→    this.decisionApi.getContext(id).subscribe({
145→      next: (ctx) =>
146→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
147→      error: () => {},
148→    });
149→    this.decisionApi.getEngineDecisions(id).subscribe({
150→      next: (decisions) => this.store.applyDecisions(decisions),
151→      error: () => {},
152→    });
153→    this.connSub = this.ws.connected$.subscribe((connected) => {
154→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
155→    });
156→    this.tick.start(this.store);
157→  }
158→
159→  private loadSnapshot(exerciseId: number): void {
160→    this.api.snapshot(exerciseId).subscribe({
161→      next: (snap) => {
162→        this.snapshotLoaded = true;
163→        this.store.applySnapshot(snap);
164→      },
165→      error: () => this.store.setError("Failed to load snapshot"),
166→    });
167→  }
168→
169→  protected onBeginExercise(): void {
170→    this.beginningExercise.set(true);
171→    this.api.begin(this.exerciseId()).subscribe({
172→      next: (change) => {
173→        this.store.applyPhaseChange(change.phase);
174→        this.store.applyTimeUpdate(change.time);
175→        this.beginningExercise.set(false);
176→      },
177→      error: () => {
178→        this.store.setError("Failed to begin exercise");
179→        this.beginningExercise.set(false);
180→      },
181→    });
182→  }
183→
184→  protected onStop(): void {
185→    this.api.stop(this.exerciseId()).subscribe({
186→      next: () => this.onExerciseStopped(),
187→    });
188→  }
189→
190→  private onExerciseStopped(): void {
191→    this.ws.disconnect();
192→    this.router.navigate(["/"]);
193→  }
194→
195→  ngOnDestroy(): void {
196→    this.tick.stop();
197→    this.ws.disconnect();
198→    this.sub?.unsubscribe();
199→    this.connSub?.unsubscribe();
200→  }
201→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
202→    const decision = this.activeDecisions()[0];
203→    if (!decision) return;
204→    const role = this.store.context()?.roles?.find(
205→      (r) => r.id === submission.roleId,
206→    );
207→    if (role?.player_type === "decision_maker") {
208→      submitDecision(
209→        this.decisionApi,
210→        this.store,
211→        this.exerciseId(),
212→        decision,
213→        submission,
214→      );
215→    } else {
216→      submitRoleRecommendation(
217→        this.decisionApi,
218→        this.exerciseId(),
219→        decision,
220→        this.participantId(),
221→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
222→      );
223→    }
224→    const updated = new Set(this.submittedRoles());
225→    updated.add(submission.roleId);
226→    this.submittedRoles.set(updated);
227→  }
228→}
