 1→import type { ActiveDecision } from "./decision-api.service";
 2→import type { ExerciseStore } from "./exercise.store";
 3→import type {
 4→  StateChange,
 5→  DecisionOpened,
 6→} from "./generated/state-changes.types";
 7→
 8→type StoreInstance = InstanceType<typeof ExerciseStore>;
 9→
10→/** Convert a decision_opened state change to an ActiveDecision for the store. */
11→export function toActiveDecision(c: DecisionOpened): ActiveDecision {
12→  return {
13→    id: c.id,
14→    event_id: c.event_id,
15→    issue_id: c.issue_id,
16→    title: c.title,
17→    description: c.description,
18→    question_type: c.question_type,
19→    options: c.options,
20→    completion_mode: c.completion_mode,
21→    target_roles: c.target_roles,
22→    timeout_ms: c.timeout_ms,
23→    max_selections: c.max_selections,
24→    status: "open",
25→    opened_at_pt_ms: c.opened_at_pt_ms,
26→    closed_at_pt_ms: null,
27→    recommendations: c.recommendations ?? {},
28→    selected_option_ids: [],
29→  };
30→}
31→
32→/** Apply a single state change to the exercise store. */
33→export function handleStateChange(
34→  change: StateChange,
35→  store: StoreInstance,
36→): void {
37→  switch (change.type) {
38→    case "phase_change":
39→      store.applyPhaseChange(change.phase);
40→      store.applyTimeUpdate(change.time);
41→      break;
42→    case "event_change":
43→      store.updateEvent(change.event_id, change.lifecycle);
44→      break;
45→    case "issue_change":
46→      store.updateIssue(change.issue_id, change.lifecycle, change.released);
47→      break;
48→    case "decision_opened":
49→      store.applyDecisions([
50→        ...store.decisions(),
51→        toActiveDecision(change),
52→      ]);
53→      break;
54→    case "decision_closed":
55→      store.closeDecision(change.decision_id, change.selected_option_ids);
56→      break;
57→    case "score_change":
58→      store.applyScoreChange(change);
59→      break;
60→    case "recommendation_submitted":
61→      store.applyRecommendation(
62→        change.decision_id,
63→        change.participant_id,
64→        change.option_id,
65→      );
66→      break;
67→    case "speed_change":
68→      store.setSpeedFactor(change.factor);
69→      break;
70→    case "forced_card_applied":
71→      // No UI action needed — forced cards are reflected in the decision's options
72→      break;
73→    case "system_state_change":
74→      store.applySystemChange(change);
75→      break;
76→  }
77→}
